  function pAct(a){ var p=curP; if(!p)return; if(a==='buy'){ var c=pcost(p); if(P.pp>=c){ P.pp-=c; p.owner='you'; p.care=1; p.furn=p.furn||[]; flora[p.zone]=Math.min(1,(flora[p.zone]||.5)+.1); rParcel(); rInv(); save(); toast('🏠 Parcela comprada en '+p.zone); logC('Nueva tierra: '+p.zone); } else toast('💠 PP insuficientes'); } else if(a==='work'){ p.care=Math.min(1,p.care+.25); flora[p.zone]=Math.min(1,(flora[p.zone]||.5)+.03); var g=Math.round((2+p.level)*dir.mult); P.pp+=g; toast('💼 +'+g+' 💠 y la zona florece'); rParcel(); rInv(); save(); } else if(a==='upgrade'){ var c=pcost({level:p.level+1}); if(P.pp>=c){ P.pp-=c; p.level++; toast('⬆️ Nivel '+p.level); logC('Mejoraste parcela a nivel '+p.level); rParcel(); rInv(); save(); } else toast('💠 PP insuficientes'); } else if(a==='rent'){ p.rent=!p.rent; toast(p.rent?'📜 Arrendada (pasiva)':'Renta quitada'); logC(p.rent?'Arrendaste parcela':'Quitaste renta'); rParcel(); save(); } else if(a==='collect'){ if(p.acc>=1){ var g=Math.floor(p.acc); P.pp+=g; p.acc-=g; toast('💰 +'+g.toFixed(0)+' 💠'); rParcel(); rInv(); save(); } else toast('Sin renta acumulada'); } }
