  function refP2P(){ while(P2P.length<5){ var zs=['Aldea Aurora','Bosque Susurrante','Ciudad Nexus','Crater Lunar'], ss=['Kai_77','Nova_X','Luna_eth','Ash_Dev','Pixel_Sol','Mika','Orion_Z','Vega_42'], rl=Math.random(); var nm={id:'m'+(Math.random().toString(36).slice(2,7)),seller:ss[Math.floor(Math.random()*ss.length)]}; if(rl<.6){ nm.kind='tierra'; nm.zone=zs[Math.floor(Math.random()*zs.length)]; nm.emoji=nm.zone==='Aldea Aurora'?'🏞️':nm.zone==='Bosque Susurrante'?'🌲':nm.zone==='Ciudad Nexus'?'🌆':'🌑'; nm.price=Math.round(1200+Math.random()*2200); } else if(rl<.8){ nm.kind='montura'; nm.give='cometa'; nm.emoji='☄️'; nm.price=Math.round(700+Math.random()*500); } else { var cs=['aegis','tel_espejo','pluma_cefiro']; nm.give=cs[Math.floor(Math.random()*cs.length)]; nm.kind='cosmetico'; nm.emoji=ITEMS[nm.give].emoji; nm.price=Math.round(ITEMS[nm.give].val*(2+Math.random()*2)); } nm.base=nm.price; nm.tr=(Math.random()<.5?1:-1); P2P.push(nm); } }
